import re

# MainViewModel.cs
with open('CipherVault/ViewModels/MainViewModel.cs', 'r') as f:
    content = f.read()

content = content.replace('using System.Windows;', 'using System.Windows;\nusing System.Linq;')
content = content.replace('private string _searchText = string.Empty;', 'private string _searchText = string.Empty;\n\n        public ObservableCollection<VaultItem> AllVaultItems { get; } = new();\n        public ObservableCollection<VaultItem> FilteredVaultItems { get; } = new();')
content = content.replace('IconType = "Plus" }\n                }\n            };', 'IconType = "Plus" }\n                }\n            };\n\n            AllVaultItems.Add(_selectedVaultItem);\n            FilteredVaultItems.Add(_selectedVaultItem);\n        }\n\n        partial void OnSearchTextChanged(string value)\n        {\n            FilteredVaultItems.Clear();\n            if (string.IsNullOrWhiteSpace(value))\n            {\n                foreach (var item in AllVaultItems)\n                {\n                    FilteredVaultItems.Add(item);\n                }\n            }\n            else\n            {\n                var lowerSearch = value.ToLowerInvariant();\n                foreach (var item in AllVaultItems.Where(i => i.Title.ToLowerInvariant().Contains(lowerSearch) || i.Category.ToLowerInvariant().Contains(lowerSearch)))\n                {\n                    FilteredVaultItems.Add(item);\n                }\n            }')
content = content.replace('        private void AddNewItem()\n        {\n            // Add new item logic\n        }', '        private void AddNewItem()\n        {\n            // Add new item logic\n        }\n\n        [RelayCommand]\n        private void ViewAuditTrail()\n        {\n            // View audit trail logic\n        }')

with open('CipherVault/ViewModels/MainViewModel.cs', 'w') as f:
    f.write(content)

# MainWindow.xaml
with open('CipherVault/MainWindow.xaml', 'r') as f:
    content = f.read()

content = content.replace('<ContentPresenter Margin="24,12"/>', '<StackPanel Orientation="Horizontal" Margin="24,12">\n                                <TextBlock Text="{TemplateBinding Tag}" FontFamily="Segoe MDL2 Assets" FontSize="16" Margin="0,0,12,0" VerticalAlignment="Center"/>\n                                <ContentPresenter VerticalAlignment="Center"/>\n                            </StackPanel>')

content = content.replace('<RadioButton Content="Vault" IsChecked="True" Style="{StaticResource SidebarMenuBtn}" GroupName="Nav"/>', '<RadioButton Content="Vault" Tag="&#xE785;" IsChecked="True" Style="{StaticResource SidebarMenuBtn}" GroupName="Nav"/>')
content = content.replace('<RadioButton Content="Favorites" Style="{StaticResource SidebarMenuBtn}" GroupName="Nav"/>', '<RadioButton Content="Favorites" Tag="&#xE728;" Style="{StaticResource SidebarMenuBtn}" GroupName="Nav"/>')
content = content.replace('<RadioButton Content="Security Audit" Style="{StaticResource SidebarMenuBtn}" GroupName="Nav"/>', '<RadioButton Content="Security Audit" Tag="&#xE713;" Style="{StaticResource SidebarMenuBtn}" GroupName="Nav"/>')
content = content.replace('<RadioButton Content="Settings" Style="{StaticResource SidebarMenuBtn}" GroupName="Nav"/>', '<RadioButton Content="Settings" Tag="&#xE713;" Style="{StaticResource SidebarMenuBtn}" GroupName="Nav"/>')

content = content.replace('<TextBlock Text="Search vault items..." Foreground="{StaticResource TextMutedBrush}" VerticalAlignment="Center" IsHitTestVisible="False" Margin="24,0,0,0"/>\n                                <TextBox Background="Transparent" BorderThickness="0" VerticalAlignment="Center" Text="{Binding SearchText, UpdateSourceTrigger=PropertyChanged}" Padding="24,0,0,0"/>', '<TextBlock Text="&#xE721;" FontFamily="Segoe MDL2 Assets" Foreground="{StaticResource TextMutedBrush}" VerticalAlignment="Center" Margin="0,0,0,0"/>\n                                <TextBlock Text="Search vault items..." Foreground="{StaticResource TextMutedBrush}" VerticalAlignment="Center" IsHitTestVisible="False" Margin="24,0,0,0">\n                                    <TextBlock.Style>\n                                        <Style TargetType="TextBlock">\n                                            <Setter Property="Visibility" Value="Collapsed"/>\n                                            <Style.Triggers>\n                                                <DataTrigger Binding="{Binding Text.Length, ElementName=SearchTextBox}" Value="0">\n                                                    <Setter Property="Visibility" Value="Visible"/>\n                                                </DataTrigger>\n                                            </Style.Triggers>\n                                        </Style>\n                                    </TextBlock.Style>\n                                </TextBlock>\n                                <TextBox x:Name="SearchTextBox" Background="Transparent" BorderThickness="0" VerticalAlignment="Center" Text="{Binding SearchText, UpdateSourceTrigger=PropertyChanged}" Padding="24,0,0,0"/>')

content = content.replace('<Button Content="🔄" Style="{StaticResource ActionBtn}" Margin="0,0,4,0"/>', '<Button Content="&#xE895;" FontFamily="Segoe MDL2 Assets" Style="{StaticResource ActionBtn}" Margin="0,0,4,0"/>')
content = content.replace('<Button Content="❓" Style="{StaticResource ActionBtn}" Margin="0,0,4,0"/>', '<Button Content="&#xE897;" FontFamily="Segoe MDL2 Assets" Style="{StaticResource ActionBtn}" Margin="0,0,4,0"/>')
content = content.replace('<Button Content="👤" Style="{StaticResource ActionBtn}" Margin="0,0,16,0"/>', '<Button Content="&#xE77B;" FontFamily="Segoe MDL2 Assets" Style="{StaticResource ActionBtn}" Margin="0,0,16,0"/>')

content = content.replace('<TextBox Text="{Binding SelectedVaultItem.Username}"  IsReadOnly="True"/>', '<TextBox Style="{StaticResource MonoInput}" Text="{Binding SelectedVaultItem.Username}" IsReadOnly="True" Padding="12,10,48,10"/>')
content = content.replace('<Button Content="Copy" Style="{StaticResource ActionBtn}" HorizontalAlignment="Right" Margin="4" Command="{Binding CopyToClipboardCommand}" CommandParameter="{Binding SelectedVaultItem.Username}"/>', '<Button Content="&#xE8C8;" FontFamily="Segoe MDL2 Assets" Style="{StaticResource ActionBtn}" HorizontalAlignment="Right" Margin="4" Command="{Binding CopyToClipboardCommand}" CommandParameter="{Binding SelectedVaultItem.Username}"/>')

content = content.replace('<TextBox  IsReadOnly="True" x:Name="PasswordBox">', '<TextBox IsReadOnly="True" x:Name="PasswordBox" Padding="12,10,76,10">')
content = content.replace('<Button Content="Show" Style="{StaticResource ActionBtn}" Command="{Binding TogglePasswordVisibilityCommand}"/>', '<Button Style="{StaticResource ActionBtn}" Command="{Binding TogglePasswordVisibilityCommand}">\n                                                <Button.Content>\n                                                    <TextBlock FontFamily="Segoe MDL2 Assets">\n                                                        <TextBlock.Style>\n                                                            <Style TargetType="TextBlock">\n                                                                <Setter Property="Text" Value="&#xE890;"/>\n                                                                <Style.Triggers>\n                                                                    <DataTrigger Binding="{Binding IsPasswordVisible}" Value="True">\n                                                                        <Setter Property="Text" Value="&#xED1A;"/>\n                                                                    </DataTrigger>\n                                                                </Style.Triggers>\n                                                            </Style>\n                                                        </TextBlock.Style>\n                                                    </TextBlock>\n                                                </Button.Content>\n                                            </Button>')
content = content.replace('<Button Content="Copy" Style="{StaticResource ActionBtn}" Command="{Binding CopyToClipboardCommand}" CommandParameter="{Binding SelectedVaultItem.EncryptedPassword}"/>', '<Button Content="&#xE8C8;" FontFamily="Segoe MDL2 Assets" Style="{StaticResource ActionBtn}" Command="{Binding CopyToClipboardCommand}" CommandParameter="{Binding SelectedVaultItem.EncryptedPassword}"/>')

content = content.replace('<TextBox Text="{Binding SelectedVaultItem.Url}"  IsReadOnly="True"/>', '<TextBox Style="{StaticResource MonoInput}" Text="{Binding SelectedVaultItem.Url}" IsReadOnly="True" Padding="12,10,48,10"/>')
content = content.replace('<Button Content="Open" Style="{StaticResource ActionBtn}" HorizontalAlignment="Right" Margin="4" Command="{Binding LaunchExternalUrlCommand}" CommandParameter="{Binding SelectedVaultItem.Url}"/>', '<Button Content="&#xE8A7;" FontFamily="Segoe MDL2 Assets" Style="{StaticResource ActionBtn}" HorizontalAlignment="Right" Margin="4" Command="{Binding LaunchExternalUrlCommand}" CommandParameter="{Binding SelectedVaultItem.Url}"/>')

content = content.replace('<TextBlock Text="🛡" FontSize="16" Margin="0,0,12,0"/>', '<TextBlock Text="&#xEA18;" FontFamily="Segoe MDL2 Assets" FontSize="16" Margin="0,0,12,0"/>')
content = content.replace('<TextBlock Text="📅" FontSize="16" Margin="0,0,12,0"/>', '<TextBlock Text="&#xE787;" FontFamily="Segoe MDL2 Assets" FontSize="16" Margin="0,0,12,0"/>')
content = content.replace('<TextBlock Text="✓" FontSize="16" Margin="0,0,12,0" Foreground="{StaticResource PrimaryBrush}"/>', '<TextBlock Text="&#xE81C;" FontFamily="Segoe MDL2 Assets" FontSize="16" Margin="0,0,12,0" Foreground="{StaticResource PrimaryBrush}"/>')

content = content.replace('<!-- Icon Badge -->\n                                                <Border Width="24" Height="24" CornerRadius="12" Background="#F1F5F9" Margin="0,0,12,0" VerticalAlignment="Top">\n                                                    <TextBlock Text="•" VerticalAlignment="Center" HorizontalAlignment="Center" Foreground="{StaticResource TextMutedBrush}"/>\n                                                </Border>', '<!-- Vertical Timeline Line -->\n                                                <Border Width="2" Background="{StaticResource BorderBrush}" Margin="11,24,0,-16" HorizontalAlignment="Left"/>\n                                                <!-- Icon Badge -->\n                                                <Border Width="24" Height="24" CornerRadius="12" Background="#F1F5F9" Margin="0,0,12,0" VerticalAlignment="Top">\n                                                    <TextBlock FontFamily="Segoe MDL2 Assets" VerticalAlignment="Center" HorizontalAlignment="Center">\n                                                        <TextBlock.Style>\n                                                            <Style TargetType="TextBlock">\n                                                                <Setter Property="Foreground" Value="{StaticResource TextMutedBrush}"/>\n                                                                <Setter Property="Text" Value="&#xE711;"/>\n                                                                <Style.Triggers>\n                                                                    <DataTrigger Binding="{Binding IconType}" Value="Pencil">\n                                                                        <Setter Property="Text" Value="&#xE70F;"/>\n                                                                        <Setter Property="Foreground" Value="{StaticResource PrimaryBrush}"/>\n                                                                    </DataTrigger>\n                                                                    <DataTrigger Binding="{Binding IconType}" Value="Eye">\n                                                                        <Setter Property="Text" Value="&#xE890;"/>\n                                                                    </DataTrigger>\n                                                                    <DataTrigger Binding="{Binding IconType}" Value="Copy">\n                                                                        <Setter Property="Text" Value="&#xE8C8;"/>\n                                                                    </DataTrigger>\n                                                                    <DataTrigger Binding="{Binding IconType}" Value="Plus">\n                                                                        <Setter Property="Text" Value="&#xE710;"/>\n                                                                    </DataTrigger>\n                                                                </Style.Triggers>\n                                                            </Style>\n                                                        </TextBlock.Style>\n                                                    </TextBlock>\n                                                </Border>')

content = content.replace('<TextBlock Text="View full audit trail" Foreground="{StaticResource PrimaryBrush}" Style="{StaticResource BaseText}" FontSize="13" Margin="0,8,0,0" Cursor="Hand"/>', '<Button Style="{StaticResource ActionBtn}" Padding="0" Margin="0,8,0,0" HorizontalAlignment="Left" Command="{Binding DataContext.ViewAuditTrailCommand, RelativeSource={RelativeSource AncestorType=Window}}">\n                                    <Button.Content>\n                                        <TextBlock Text="View full audit trail" Foreground="{StaticResource PrimaryBrush}" Style="{StaticResource BaseText}" FontSize="13" Cursor="Hand"/>\n                                    </Button.Content>\n                                </Button>')

with open('CipherVault/MainWindow.xaml', 'w') as f:
    f.write(content)
